-- GEGENEREERD door scripts/nutrition/generate-seed.mjs; niet met de hand wijzigen.
--
-- Voedingswaarden: NEVO-online 2025/9.0, RIVM, Bilthoven. Ongewijzigd overgenomen,
-- zoals de gebruiksvoorwaarden vragen. Clubrecepten: scripts/nutrition/standard-recipes.json.
--
-- Idempotent: voedingsmiddelen worden bijgewerkt op nevo_code, clubrecepten op
-- slug, en de ingrediënten van clubrecepten worden opnieuw opgebouwd. Eigen
-- recepten van leden blijven onaangeroerd.

on conflict (nevo_code) do update set
  name_nl = excluded.name_nl,
  quantity_unit = excluded.quantity_unit,
  food_group = excluded.food_group,
  kcal = excluded.kcal,
  carbs_g = excluded.carbs_g,
  sugars_g = excluded.sugars_g,
  protein_g = excluded.protein_g,
  fat_g = excluded.fat_g,
  fiber_g = excluded.fiber_g,
  sodium_mg = excluded.sodium_mg,
  calcium_mg = excluded.calcium_mg,
  iron_mg = excluded.iron_mg,
  magnesium_mg = excluded.magnesium_mg,
  zinc_mg = excluded.zinc_mg,
  vitamin_d_ug = excluded.vitamin_d_ug,
  vitamin_c_mg = excluded.vitamin_c_mg,
  epa_g = excluded.epa_g,
  dha_g = excluded.dha_g,
  nevo_version = excluded.nevo_version;

2. Haal van het vuur en roer de kwark erdoor.
3. Snijd de banaan in plakjes, leg ze erop en maak af met de honing.', null, null, true, null),
  ('overnight-oats-skyr', 'Overnight oats met skyr en blauwe bessen', 'ontbijt', 'gemengd', array['vegetarisch']::text[], 1, 5, '1. Meng de havervlokken met de melk, de skyr, de honing en de kaneel in een pot.
2. Zet de pot een nacht afgedekt in de koelkast.
3. Schep ''s ochtends de blauwe bessen erdoor.', null, null, true, null),
  ('roerei-volkorenbrood', 'Roerei met spinazie op volkorenbrood', 'ontbijt', 'eiwitrijk', array['vegetarisch']::text[], 1, 10, '1. Verhit de olie en laat de spinazie kort slinken.
2. Klop de eieren los, giet ze in de pan en roer op laag vuur tot ze net gestold zijn.
3. Serveer op het brood met plakjes tomaat.', null, null, true, null),
  ('wrap-kip-hummus', 'Volkorenwrap met kip en hummus', 'lunch', 'gemengd', array[]::text[], 2, 15, '1. Snijd de kipfilet in reepjes en bak ze in de olie gaar.
2. Snijd de paprika en de komkommer in reepjes.
3. Besmeer de wraps met hummus, beleg met sla, groente en kip en rol ze op.', null, null, true, null),
  ('linzensalade-feta', 'Linzensalade met feta', 'lunch', 'gemengd', array['vegetarisch', 'glutenvrij']::text[], 2, 30, '1. Kook de linzen in ruim water in ongeveer 20 minuten beetgaar en laat ze uitlekken.
2. Snijd de tomaat, de komkommer en de ui klein.
3. Meng alles met de olie en het citroensap en verkruimel de feta erover.', null, null, true, null),
  ('couscous-kikkererwten', 'Couscous met kikkererwten en rozijnen', 'lunch', 'hoog_kh', array['vegetarisch', 'vegan']::text[], 2, 20, '1. Overgiet de couscous met evenveel kokend water, dek af en laat 5 minuten staan.
2. Spoel de kikkererwten af en snijd de paprika en de komkommer klein.
3. Maak de couscous los met een vork en meng alles met de rozijnen, de olie en het citroensap.', null, null, true, null),
  ('broodjes-tonijnsalade', 'Volkorenbrood met tonijnsalade', 'lunch', 'eiwitrijk', array[]::text[], 1, 10, '1. Laat de tonijn uitlekken en prak hem met de yoghurt.
2. Beleg het brood met sla, tonijnsalade en plakjes tomaat.', null, null, true, null),
  ('pasta-kip-tomaat', 'Pasta met kip en tomatensaus', 'diner', 'hoog_kh', array[]::text[], 2, 25, '1. Kook de pasta volgens de verpakking.
2. Fruit de ui en de knoflook in de olie, bak de kip in blokjes gaar en voeg de paprika toe.
3. Voeg de gezeefde tomaten toe en laat 10 minuten zacht koken.
4. Meng met de pasta en strooi de Parmezaanse kaas erover.', null, null, true, null),
  ('zalm-rijst-broccoli', 'Zalm met rijst en broccoli', 'diner', 'gemengd', array['glutenvrij']::text[], 2, 25, '1. Kook de rijst volgens de verpakking.
2. Kook of stoom de broccoli in 5 minuten beetgaar.
3. Bak de zalm in de olie 3 tot 4 minuten per kant en besprenkel met citroensap.', null, null, true, null),
  ('curry-zoete-aardappel-kikkererwten', 'Curry van zoete aardappel en kikkererwten', 'diner', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij']::text[], 3, 40, '1. Kook de rijst volgens de verpakking.
2. Fruit de ui en de knoflook met de komijn en het paprikapoeder in een scheut water of wat kokosmelk.
3. Voeg de zoete aardappel in blokjes, de gezeefde tomaten en de kokosmelk toe en laat 20 minuten zacht koken.
4. Roer de kikkererwten en de spinazie erdoor en verwarm nog 5 minuten. Serveer met de rijst.', null, null, true, null),
  ('aardappelen-biefstuk-sperziebonen', 'Aardappelen met biefstuk en sperziebonen', 'diner', 'gemengd', array['glutenvrij']::text[], 2, 30, '1. Schil de aardappelen en kook ze in ongeveer 20 minuten gaar.
2. Kook de sperziebonen in 8 minuten beetgaar.
3. Bak het vlees in de olie op hoog vuur, 2 tot 3 minuten per kant, en laat het even rusten.', null, null, true, null),
  ('linzenbolognese', 'Volkorenpasta met linzenbolognese', 'diner', 'gemengd', array['vegetarisch', 'vegan']::text[], 3, 35, '1. Fruit de ui, de knoflook en de geraspte wortel in de olie.
2. Voeg de linzen, de gezeefde tomaten en 300 ml water toe en laat 25 minuten zacht koken tot de linzen gaar zijn.
3. Kook ondertussen de pasta en serveer met de saus.', null, null, true, null),
  ('tofu-roerbak-rijst', 'Roerbak met tofu en zilvervliesrijst', 'diner', 'hoog_kh', array['vegetarisch', 'vegan']::text[], 2, 25, '1. Kook de rijst volgens de verpakking.
2. Snijd de tofu in blokjes en bak ze in de olie goudbruin. Haal ze uit de pan.
3. Roerbak de groente met de geraspte gember 5 minuten.
4. Voeg de tofu en de sojasaus toe en serveer met de rijst.', null, null, true, null),
  ('brood-banaan-honing', 'Witbrood met banaan en honing', 'voor_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 5, '1. Besmeer het brood dun met pindakaas.
2. Beleg met plakjes banaan en maak af met honing.', null, null, true, null),
  ('rijstwafels-jam', 'Rijstwafels met jam', 'voor_rit', 'hoog_kh', array['vegetarisch', 'vegan']::text[], 1, 2, '1. Besmeer de rijstwafels met jam.', null, null, true, null),
  ('rijsttaartjes', 'Rijsttaartjes voor onderweg', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'glutenvrij']::text[], 6, 40, '1. Kook de rijst met wat extra water tot hij zacht en plakkerig is. Laat afkoelen.
2. Prak de banaan en meng hem met de honing en het zout door de rijst.
3. Druk het mengsel stevig in een ingevette bakvorm en laat een nacht opstijven in de koelkast.
4. Snijd in zes stukken en pak ze per stuk in folie. Eén stuk is één portie.', null, null, true, null),
  ('sportdrank-zelfgemaakt', 'Zelfgemaakte sportdrank', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij']::text[], 1, 2, '1. Los de suiker en het zout op in een scheut warm water in de bidon.
2. Voeg de siroop toe en vul aan met koud water tot 750 ml.
3. Eén bidon is één portie, voor ongeveer een uur. Gewone suiker bevat glucose en fructose in een verhouding van 1:1.', null, null, true, null),
  ('dadelrepen', 'Dadel-haverrepen', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'vegan']::text[], 8, 20, '1. Maal de dadels in een keukenmachine tot een pasta.
2. Voeg de havervlokken, de pindakaas en het zout toe en maal tot een samenhangende massa.
3. Druk plat in een bakvorm en laat een uur opstijven in de koelkast.
4. Snijd in acht repen en pak ze per stuk in. Eén reep is één portie.', null, null, true, null),
  ('herstelshake', 'Herstelshake met banaan en kwark', 'na_rit', 'gemengd', array['vegetarisch']::text[], 1, 5, '1. Doe alles in een blender en mix tot een gladde shake.', null, null, true, null),
  ('chocolademelk-krentenbol', 'Chocolademelk met een krentenbol', 'na_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 1, '1. Drink de chocolademelk en eet de krentenbol, het liefst binnen een uur na de rit.', null, null, true, null),
  ('kwark-walnoten-bessen', 'Kwark met blauwe bessen en walnoten', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Schep de kwark in een kom en maak af met de bessen, de gehakte walnoten en de kaneel.', null, null, true, null),
  ('huttenkase-peer', 'Hüttenkäse met peer en kaneel', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Snijd de peer in blokjes en meng met de hüttenkäse. Strooi de kaneel erover.', null, null, true, null),
  ('sojayoghurt-pindakaas', 'Sojayoghurt met pindakaas en bessen', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'vegan']::text[], 1, 3, '1. Roer de pindakaas door de sojayoghurt en maak af met de blauwe bessen.', null, null, true, null),
  ('yoghurt-muesli-appel', 'Yoghurt met muesli en appel', 'tussendoor', 'gemengd', array['vegetarisch']::text[], 1, 3, '1. Schep de yoghurt in een kom, snijd de appel in stukjes en strooi de muesli erover.', null, null, true, null),
  ('bircher-muesli', 'Bircher muesli met abrikoos en appel', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 4, 10, '1. Meng de havervlokken met de fijngesneden abrikozen, het sinaasappelsap, de melk, de yoghurt en de noten.
2. Rasp de appel erdoor en zet de kom een nacht afgedekt in de koelkast.
3. Schep in kommen en maak af met plakjes banaan en de honing.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/bircher_muesli', true, null),
  ('eiwitrijke-havermout', 'Havermout met extra eiwit', 'ontbijt', 'gemengd', array['vegetarisch']::text[], 1, 8, '1. Breng de havervlokken met de melk en een snuf zout aan de kook en laat al roerend een minuut doorkoken.
2. Haal van het vuur en roer de skyr erdoor.
3. Leg de banaan en de amandelen erop en schenk de honing erover.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/porridge', true, null),
  ('pannenkoekjes-yoghurt-honing', 'Kleine pannenkoekjes met yoghurt en honing', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 2, 20, '1. Meng het bakmeel met de suiker. Klop het ei los met de yoghurt en de melk en roer dit door het meel tot een glad beslag.
2. Verhit de boter in een koekenpan en bak van lepels beslag kleine pannenkoekjes; keer ze als er belletjes verschijnen.
3. Serveer warm met de Griekse yoghurt, de bessen en de honing.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/pikelets', true, null),
  ('pannenkoeken-banaan', 'Pannenkoeken met banaan', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 2, 25, '1. Klop de bloem met de eieren, de melk en een snuf zout tot een glad beslag.
2. Bak in een beetje olie vier pannenkoeken.
3. Beleg met plakjes banaan, schenk de stroop erover en serveer met de kwark.', null, null, true, null),
  ('brood-pindakaas-banaan', 'Volkorenbrood met pindakaas en banaan', 'ontbijt', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 5, '1. Besmeer het brood met de pindakaas.
2. Beleg met plakjes banaan en drink er de sojadrink bij.', null, null, true, null),
  ('yoghurt-muesli-fruit', 'Yoghurt met muesli en vers fruit', 'ontbijt', 'gemengd', array['vegetarisch']::text[], 1, 5, '1. Schep de yoghurt in een kom.
2. Verdeel de muesli, de aardbeien en de kiwi erover en maak af met de honing.', null, null, true, null),
  ('wentelteefjes', 'Wentelteefjes met kaneel en appel', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 2, 15, '1. Klop de eieren los met de melk en de kaneel en week de sneden brood er kort in.
2. Bak ze in de boter aan beide kanten goudbruin.
3. Snijd de appel in dunne partjes, leg ze erop en bestrooi met de suiker.', null, null, true, null),
  ('cornflakes-banaan', 'Cornflakes met banaan en melk', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 1, 3, '1. Doe de cornflakes in een kom en snijd de banaan erboven in plakjes.
2. Schenk de melk erover en eet de yoghurt met honing ernaast.', null, null, true, null),
  ('witbrood-jam-yoghurt', 'Witbrood met jam en een schaaltje yoghurt', 'ontbijt', 'hoog_kh', array['vegetarisch']::text[], 1, 5, '1. Besmeer het brood met de jam.
2. Roer de honing door de yoghurt en eet die ernaast.
3. Drink er het sinaasappelsap bij.', null, null, true, null),
  ('omelet-groente-brood', 'Groenteomelet met volkorenbrood', 'ontbijt', 'eiwitrijk', array['vegetarisch']::text[], 1, 12, '1. Snijd de paprika en de champignons klein en bak ze in de olie.
2. Klop de eieren los met peper en zout, giet ze over de groente en laat op laag vuur stollen.
3. Strooi de kaas erover en serveer met het brood.', null, null, true, null),
  ('havermout-appel-kaneel', 'Havermout met appel en kaneel', 'ontbijt', 'hoog_kh', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 10, '1. Snijd de appel in blokjes.
2. Breng de havervlokken met de sojadrink, de appel en de kaneel aan de kook en laat 3 minuten zacht koken.
3. Roer de rozijnen erdoor en maak af met de ahornsiroop.', null, null, true, null),
  ('broodjes-zalm-ei', 'Broodjes met gerookte zalm en ei', 'ontbijt', 'eiwitrijk', array[]::text[], 1, 10, '1. Kook het ei in 8 minuten hard en snijd het in plakjes.
2. Besmeer de broodjes met de hüttenkäse.
3. Beleg met de zalm, het ei, de komkommer en wat peper.', null, null, true, null),
  ('broodje-rosbief', 'Broodje rosbief met tomaat en komkommer', 'lunch', 'gemengd', array[]::text[], 1, 5, '1. Snijd de broodjes open en besmeer ze met de mosterd.
2. Beleg met de rosbief, de plakjes komkommer en tomaat en de sla.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/roast_beef_bagel', true, null),
  ('pastasalade-kip', 'Pastasalade met kip en citroen-yoghurtdressing', 'lunch', 'hoog_kh', array[]::text[], 4, 25, '1. Kook de pasta beetgaar en kook de doperwten, de maïs en de wortel de laatste 3 minuten mee. Giet af en laat afkoelen.
2. Bak de kipfilet in de olie gaar en snijd hem in stukjes. Snijd de bleekselderij klein.
3. Roer de yoghurt met het citroensap en peper tot een dressing en meng alles door elkaar.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/chicken_pasta_salad', true, null),
  ('noedelsalade-zalm', 'Aziatische noedelsalade met zalm', 'lunch', 'gemengd', array['glutenvrij', 'lactosevrij']::text[], 4, 25, '1. Snijd de paksoi, de peultjes, de wortel en de paprika in reepjes en blancheer ze 1 minuut. Spoel koud af.
2. Bak de zalm in de olie 3 minuten per kant.
3. Meng de mihoen met de groente en de maïs, maak aan met het citroensap, de gember en de honing en leg de zalm erop.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/sarahs_asian_salmon_salad', true, null),
  ('minestrone-brood', 'Minestrone met witte bonen en stokbrood', 'lunch', 'gemengd', array[]::text[], 4, 35, '1. Fruit de ui met de ham in de olie. Voeg de wortel, de courgette en de tomaat in stukjes toe.
2. Schenk er 1 liter water bij met het bouillonpoeder en laat 15 minuten zacht koken.
3. Voeg de pasta, de doperwten en de bonen toe en kook nog 10 minuten. Serveer met het stokbrood.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/minestrone_by_nathan', true, null),
  ('linzenburgers-brood', 'Linzenburgers met volkorenbrood', 'lunch', 'gemengd', array['vegetarisch']::text[], 4, 40, '1. Kook de aardappel in blokjes gaar en prak hem fijn.
2. Meng de aardappel met de uitgelekte linzen, het paneermeel, het ei, de zaden, de amandelen, de ui, de knoflook en de peterselie en vorm acht burgers.
3. Bak ze in de olie aan beide kanten bruin en serveer met het brood en de sla.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/taylor-_made_lentil_patties', true, null),
  ('pita-kip-hummus', 'Pita met kip, hummus en rauwkost', 'lunch', 'gemengd', array[]::text[], 2, 15, '1. Snijd de kipfilet in reepjes, bestrooi met het paprikapoeder en bak ze in de olie gaar.
2. Rooster de pita''s en snijd ze open.
3. Besmeer met de hummus en vul met de kip, de komkommer, de tomaat en de sla.', null, null, true, null),
  ('rijstsalade-tonijn-mais', 'Rijstsalade met tonijn en maïs', 'lunch', 'hoog_kh', array['glutenvrij', 'lactosevrij']::text[], 2, 20, '1. Kook de rijst gaar en laat hem afkoelen.
2. Snijd de paprika en de bosui klein.
3. Meng de rijst met de uitgelekte tonijn, de maïs en de groente en maak aan met de olie en het citroensap.', null, null, true, null),
  ('omelet-ham-brood', 'Omelet met ham op brood', 'lunch', 'eiwitrijk', array[]::text[], 1, 10, '1. Klop de eieren los met peper en bak er in de olie een omelet van.
2. Leg de ham op het brood en de omelet erop.
3. Serveer met de tomaat in plakjes.', null, null, true, null),
  ('aardappelsalade-ei', 'Aardappelsalade met ei en sperziebonen', 'lunch', 'gemengd', array['vegetarisch', 'glutenvrij']::text[], 2, 25, '1. Kook de aardappelen in stukken in 15 minuten gaar en kook de sperziebonen de laatste 6 minuten mee.
2. Kook de eieren in 8 minuten hard en snijd ze in partjes.
3. Roer de yoghurt met de mosterd en de bieslook tot een dressing en meng alles door elkaar.', null, null, true, null),
  ('bulgursalade-kikkererwten', 'Bulgursalade met kikkererwten en munt', 'lunch', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 2, 20, '1. Kook de bulgur in 10 minuten gaar en laat hem afkoelen.
2. Snijd de komkommer, de tomaat en de rode ui klein en hak de munt en de peterselie.
3. Meng alles met de uitgelekte kikkererwten, de olie en het citroensap.', null, null, true, null),
  ('wrap-zalm-huttenkase', 'Wrap met gerookte zalm en hüttenkäse', 'lunch', 'eiwitrijk', array[]::text[], 1, 5, '1. Besmeer de wraps met de hüttenkäse.
2. Beleg met de zalm, de komkommer en de rucola en rol ze op.', null, null, true, null),
  ('linzensoep-brood', 'Tomaten-linzensoep met brood', 'lunch', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 2, 30, '1. Fruit de ui, de knoflook en de wortel in de olie met de komijn.
2. Voeg de linzen, de gezeefde tomaat en 500 ml water met het zout toe en kook 25 minuten.
3. Pureer grof en serveer met het brood.', null, null, true, null),
  ('quinoasalade-biet-feta', 'Quinoasalade met biet en feta', 'lunch', 'gemengd', array['vegetarisch', 'glutenvrij']::text[], 2, 20, '1. Kook de quinoa in 12 minuten gaar en laat afkoelen.
2. Snijd de biet in blokjes.
3. Meng de quinoa met de biet, de rucola en de walnoten, verkruimel de feta erover en maak aan met de olie en de balsamico.', null, null, true, null),
  ('tosti-kaas-tomaat', 'Tosti met kaas en tomaat', 'lunch', 'gemengd', array['vegetarisch']::text[], 1, 8, '1. Beleg twee sneden brood met de kaas en de tomaat in plakjes en leg de andere sneden erop.
2. Bak de tosti''s in een koekenpan of tosti-ijzer goudbruin.
3. Drink er de karnemelk bij.', null, null, true, null),
  ('pastaschotel-gehakt-groente', 'Pastaschotel met gehakt en groente', 'diner', 'gemengd', array[]::text[], 4, 45, '1. Kook de pasta beetgaar. Fruit de ui, rul het gehakt en bak de courgette, de wortel en de champignons mee.
2. Voeg de tomaten uit blik en de gezeefde tomaat toe en meng alles met de pasta in een ovenschaal.
3. Bind de melk met de maizena tot een saus, roer de kaas erdoor, giet over de schotel en bak 20 minuten op 200 °C.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/quick_pasta_casserole', true, null),
  ('ovenrisotto-rund-zoete-aardappel', 'Ovenrisotto met rundergehakt en zoete aardappel', 'diner', 'gemengd', array[]::text[], 4, 45, '1. Fruit de ui en de knoflook in de olie en rul het gehakt.
2. Meng in een ovenschaal met de rijst, 1 liter water met het bouillonpoeder, de spinazie en de zoete aardappel in kleine blokjes.
3. Bak afgedekt 20 minuten op 180 °C en daarna nog 10 minuten zonder deksel. Roer de Parmezaanse kaas erdoor.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/migration_baked_beef_risotto_2', true, null),
  ('gado-gado-pasta', 'Gado gado met pasta, ei en tofu', 'diner', 'gemengd', array['vegetarisch']::text[], 4, 30, '1. Verwarm de pindakaas met de kerrie, de sojasaus, de sambal en de melk tot een gladde saus.
2. Kook de pasta gaar. Blancheer de broccoli, de wortel, de kool en de peultjes kort.
3. Verdeel de pasta over de borden met de groente, de taugé, de hardgekookte eieren en de tofu en schenk de saus erover.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/gado_gado_with_noodles', true, null),
  ('pasta-zalm-ricotta', 'Pasta met zalm en ricotta', 'diner', 'hoog_kh', array[]::text[], 4, 25, '1. Kook de pasta beetgaar. Pocheer de zalm 8 minuten in water dat net niet kookt en pluk hem in stukken.
2. Fruit de ui, de bleekselderij en de courgette in de olie.
3. Meng de pasta met de groente, de zalm en de ricotta en maak af met het citroensap en peper.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/rigatoni_with_salmon_and_ricotta', true, null),
  ('couscous-marokkaans-rund', 'Marokkaans rundvlees met couscous', 'diner', 'gemengd', array['lactosevrij']::text[], 4, 30, '1. Bak de biefstukreepjes kort aan in de olie en haal ze uit de pan.
2. Fruit de ui met de knoflook en de komijn, voeg de tomaten, de courgette, de spinazie en de rozijnen toe en laat 5 minuten sudderen. Doe het vlees terug.
3. Wel de couscous in kokend water, roer los en serveer met het vlees en de amandelen.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/morrocan-style_beef_with_couscous', true, null),
  ('pasta-kip-mais', 'Pasta met kip en maïs', 'diner', 'hoog_kh', array[]::text[], 4, 25, '1. Kook de pasta beetgaar.
2. Bak de knoflook, de bosui, de kipreepjes en de champignons in de olie tot de kip gaar is. Voeg de maïs en de zongedroogde tomaat toe en warm door.
3. Roer van het vuur de zure room erdoor en meng met de pasta.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/pasta_with_chicken_and_corn', true, null),
  ('pasta-kip-citroen', 'Pasta met kip, citroen en doperwten', 'diner', 'hoog_kh', array[]::text[], 4, 25, '1. Kook de pasta beetgaar.
2. Bak de kipreepjes in de olie bruin, voeg 250 ml water met het bouillonpoeder, het citroensap en de doperwten toe en laat 5 minuten sudderen.
3. Roer de smeerkaas erdoor tot een saus en meng met de pasta en peper.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/fettucine_with_chicken_and_lemon', true, null),
  ('tofu-ketjap-rijst', 'Gekarameliseerde tofu met rijst', 'diner', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 4, 30, '1. Kook de rijst gaar. Bak de tofublokjes in de olie rondom bruin en haal ze uit de pan.
2. Bak de rode ui en de knoflook, voeg de ketjap, de suiker, de paprika en de peultjes toe en roerbak 3 minuten.
3. Doe de tofu terug, warm door en maak af met het citroensap.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/caramelised_tofu', true, null),
  ('pasta-witte-bonen-tonijn', 'Penne met witte bonen en tonijn', 'diner', 'hoog_kh', array['lactosevrij']::text[], 4, 20, '1. Kook de pasta beetgaar en schep de olie erdoor.
2. Snijd de tomaat in stukjes en de rode ui in dunne partjes.
3. Meng de pasta met de tomaat, de ui, de tonijn, de bonen, de peterselie, de kappertjes en het citroensap. Warm of koud te eten.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/bs_penne_with_butter_beans_and_tuna', true, null),
  ('rijst-rund-groente-japans', 'Japans rundvlees met groente op rijst', 'diner', 'hoog_kh', array['lactosevrij']::text[], 4, 30, '1. Kook de rijst gaar. Breng 500 ml water met de sojasaus en de suiker aan de kook en gaar het vlees erin.
2. Voeg de bosui, de broccoli, de peultjes, de doperwten en de paprika toe en kook 4 minuten.
3. Giet de losgeklopte eieren er in een dun straaltje bij, laat afgedekt stollen en schep over de rijst.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/japanese_beef_and_vegetables_on_rice', true, null),
  ('teriyaki-kip-rijst', 'Teriyaki-kip met rijst en groente', 'diner', 'gemengd', array['lactosevrij']::text[], 4, 30, '1. Marineer de kipreepjes een half uur in de sojasaus en de suiker. Kook de rijst gaar.
2. Breng de kip met de marinade en 400 ml water aan de kook en gaar hem met de bosui, de broccoli, de peultjes en de paprika.
3. Bind de saus met de maizena, aangelengd met wat water, en serveer over de rijst.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/teriyaki_chicken', true, null),
  ('spaghetti-chili-rund-bonen', 'Spaghetti met chili, rundergehakt en bonen', 'diner', 'hoog_kh', array['lactosevrij']::text[], 5, 30, '1. Rul het gehakt met het chilipoeder in de olie.
2. Voeg de gezeefde tomaat en 250 ml water toe en laat 15 minuten sudderen. Voeg de bonen, de maïs en de paprika toe en kook nog 5 minuten.
3. Kook intussen de spaghetti beetgaar en meng met de saus.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/spaghetti_with_chilli_beef_and_beans', true, null),
  ('tilapia-courgette-couscous', 'Tilapia met courgette en couscous', 'diner', 'eiwitrijk', array['lactosevrij']::text[], 2, 30, '1. Meng de olie met het fijngesneden basilicum en het citroensap. Leg de tilapia met de courgette in plakjes op folie, schenk de olie erover en vouw dicht.
2. Bak het pakketje 20 minuten in de oven op 175 °C.
3. Kook de broccoli in 4 minuten beetgaar en wel de couscous 10 minuten in 300 ml heet water met het bouillonpoeder.', 'Voedingscentrum', 'https://www.voedingscentrum.nl/recepten/gezond-recept/tilapia-met-courgette-en-couscous.aspx', true, null),
  ('burritos-bonen', 'Burrito''s met kidneybonen', 'diner', 'hoog_kh', array['vegetarisch']::text[], 3, 25, '1. Fruit de ui met de komijn in de olie. Voeg de bonen, de tomaten uit blik en de sambal toe en laat inkoken tot een dikke vulling.
2. Verwarm de wraps en verdeel de vulling erover.
3. Beleg met de sla, de tomaat, de kaas en de yoghurt en rol ze op.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/spicy_bean_burritos', true, null),
  ('nasi-kip-ei', 'Nasi met kip en ei', 'diner', 'hoog_kh', array['lactosevrij']::text[], 2, 30, '1. Kook de rijst gaar en laat hem uitdampen.
2. Bak de kipblokjes in de olie, voeg de prei, de wortel en de kool toe en roerbak 5 minuten.
3. Schep de rijst erdoor met de ketjap en de sambal. Bak van de eieren een omelet, snijd hem in reepjes en leg die erop.', null, null, true, null),
  ('ovenschotel-kabeljauw-aardappel', 'Ovenschotel met kabeljauw en aardappel', 'diner', 'gemengd', array['glutenvrij']::text[], 2, 45, '1. Kook de aardappelen in plakken 8 minuten voor en verdeel ze over een ovenschaal met de prei in ringen.
2. Leg de kabeljauw erop, bestrooi met peper en zout en schenk de kookroom erover.
3. Strooi de kaas erover en bak 25 minuten op 200 °C.', null, null, true, null),
  ('gnocchi-tomaat-mozzarella', 'Gnocchi met tomatensaus en mozzarella', 'diner', 'hoog_kh', array['vegetarisch']::text[], 2, 20, '1. Fruit de knoflook in de olie, voeg de gezeefde tomaat en de oregano toe en laat 10 minuten zacht koken.
2. Kook de gnocchi tot ze boven komen drijven en schep ze door de saus met de spinazie.
3. Scheur de mozzarella erover en maak af met basilicum.', null, null, true, null),
  ('risotto-champignon-doperwten', 'Risotto met champignons en doperwten', 'diner', 'hoog_kh', array['vegetarisch', 'glutenvrij']::text[], 2, 35, '1. Fruit de ui in de olie, bak de champignons mee en roer de rijst erdoor.
2. Voeg in delen 700 ml heet water met het zout toe en roer tot de rijst na ongeveer 20 minuten gaar is.
3. Roer de doperwten en de Parmezaanse kaas erdoor en warm door.', null, null, true, null),
  ('chili-sin-carne-rijst', 'Chili sin carne met rijst', 'diner', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 2, 35, '1. Kook de rijst gaar.
2. Fruit de ui, de knoflook en de paprika in de olie met het chilipoeder en de komijn.
3. Voeg de bonen, de maïs en de tomaten uit blik toe en laat 15 minuten sudderen.', null, null, true, null),
  ('traybake-kip-zoete-aardappel', 'Traybake met kip en zoete aardappel', 'diner', 'gemengd', array['glutenvrij', 'lactosevrij']::text[], 2, 40, '1. Snijd de zoete aardappel in blokjes en de rode ui en de paprika in parten.
2. Meng alles op een bakplaat met de kip in stukken, de olie, het paprikapoeder en het zout.
3. Rooster 30 minuten op 200 °C en schep halverwege om.', null, null, true, null),
  ('pasta-pesto-kip-sperziebonen', 'Pasta pesto met kip en sperziebonen', 'diner', 'hoog_kh', array[]::text[], 2, 20, '1. Kook de pasta beetgaar en kook de sperziebonen de laatste 6 minuten mee.
2. Bak de kipreepjes in de olie gaar.
3. Meng de pasta en de bonen met de pesto, de kip en de kerstomaatjes.', null, null, true, null),
  ('stamppot-boerenkool-gehaktbal', 'Boerenkoolstamppot met een gehaktbal', 'diner', 'gemengd', array['glutenvrij']::text[], 2, 40, '1. Kook de aardappelen met de boerenkool erop in 20 minuten gaar.
2. Kneed het gehakt met peper en zout, vorm twee ballen en braad ze in de olie in 15 minuten gaar.
3. Stamp de aardappelen en de kool met de melk en de mosterd tot een stamppot.', null, null, true, null),
  ('pokebowl-zalm-rijst', 'Pokébowl met zalm, rijst en komkommer', 'diner', 'gemengd', array['lactosevrij']::text[], 2, 25, '1. Kook de rijst gaar en laat hem lauw worden.
2. Bak de zalm 3 minuten per kant en snijd hem in blokjes. Snijd de komkommer, de avocado en de wortel.
3. Verdeel alles over twee kommen en maak aan met de sojasaus, de sesamolie en het sesamzaad.', null, null, true, null),
  ('dal-rode-linzen-rijst', 'Dal van linzen met rijst', 'diner', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 2, 35, '1. Kook de rijst gaar.
2. Fruit de ui, de knoflook en de gember in de olie met de kerrie. Voeg de linzen, de tomaten en 400 ml water met het zout toe en kook 25 minuten.
3. Roer de spinazie erdoor en laat slinken.', null, null, true, null),
  ('tempeh-ketjap-sperziebonen-rijst', 'Tempeh in ketjap met sperziebonen en rijst', 'diner', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 2, 30, '1. Kook de rijst gaar en de sperziebonen in 8 minuten beetgaar.
2. Bak de tempeh in blokjes in de olie bruin en voeg de knoflook toe.
3. Schep de ketjap en de sambal erdoor en serveer met de rijst en de bonen.', null, null, true, null),
  ('volkorenpasta-tonijn-tomaat', 'Volkorenpasta met tonijn-tomatensaus', 'diner', 'gemengd', array['lactosevrij']::text[], 2, 20, '1. Kook de pasta beetgaar.
2. Fruit de ui en de knoflook in de olie, voeg de gezeefde tomaat en de olijven toe en laat 10 minuten zacht koken.
3. Roer de uitgelekte tonijn en de rucola erdoor en meng met de pasta.', null, null, true, null),
  ('bananenmuffin-chocolade', 'Bananenmuffins met chocolade', 'tussendoor', 'hoog_kh', array['vegetarisch']::text[], 12, 35, '1. Meng het bakmeel, het volkorenmeel, de suiker en de gehakte chocolade.
2. Roer de gesmolten boter, de melk, het ei, de yoghurt en de geprakte bananen erdoor tot het net gemengd is.
3. Verdeel over 12 muffinvormpjes en bak 20 tot 25 minuten op 180 °C.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/banana_and_choc_muffin', true, null),
  ('abrikoos-havermuffin', 'Havermuffins met abrikoos', 'tussendoor', 'hoog_kh', array['vegetarisch']::text[], 12, 35, '1. Meng het bakmeel, het volkorenmeel, de havervlokken, de suiker en de fijngesneden abrikozen.
2. Klop de yoghurt met de melk, de eieren en de olie los en roer dit kort door het meel.
3. Verdeel over 12 muffinvormpjes en bak 20 tot 25 minuten op 180 °C.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/apricot_and_oat_muffin', true, null),
  ('krentenbol-kaas', 'Krentenbol met kaas', 'tussendoor', 'gemengd', array['vegetarisch']::text[], 1, 2, '1. Snijd de krentenbol open en beleg met de kaas.', null, null, true, null),
  ('ontbijtkoek-appel', 'Ontbijtkoek met een appel', 'tussendoor', 'hoog_kh', array['vegetarisch']::text[], 1, 1, '1. Snijd twee plakken ontbijtkoek en eet de appel erbij.', null, null, true, null),
  ('yoghurt-honing-walnoten', 'Yoghurt met honing en walnoten', 'tussendoor', 'gemengd', array['vegetarisch', 'glutenvrij']::text[], 1, 2, '1. Schep de yoghurt in een schaaltje, schenk de honing erover en strooi de walnoten erop.', null, null, true, null),
  ('rijstwafel-pindakaas-banaan', 'Rijstwafels met pindakaas en banaan', 'tussendoor', 'gemengd', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 1, 3, '1. Besmeer de rijstwafels met de pindakaas en beleg met plakjes banaan.', null, null, true, null),
  ('fruitsmoothie', 'Fruitsmoothie met banaan en aardbei', 'tussendoor', 'hoog_kh', array['vegetarisch', 'glutenvrij']::text[], 1, 5, '1. Pureer de banaan met de aardbeien, het sinaasappelsap en de yoghurt tot een gladde smoothie.', null, null, true, null),
  ('crackers-huttenkase', 'Crackers met hüttenkäse en tomaat', 'tussendoor', 'eiwitrijk', array['vegetarisch']::text[], 1, 3, '1. Beleg de crackers met de hüttenkäse en de tomaat in plakjes en bestrooi met peper.', null, null, true, null),
  ('noten-rozijnen', 'Noten met rozijnen', 'tussendoor', 'gemengd', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 1, 1, '1. Meng de noten met de rozijnen en neem ze mee in een bakje.', null, null, true, null),
  ('kwark-fruit', 'Kwark met fruit', 'tussendoor', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Snijd de peer in stukjes en schep ze met de frambozen door de kwark.
2. Maak af met de honing.', null, null, true, null),
  ('pita-hummus-wortel', 'Pita met hummus en wortel', 'tussendoor', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 5, '1. Rooster de pita en snijd hem in punten.
2. Snijd de wortel in staafjes en dip beide in de hummus.', null, null, true, null),
  ('rijstepap-kaneel', 'Rijstepap met kaneel', 'voor_rit', 'hoog_kh', array['vegetarisch', 'glutenvrij']::text[], 4, 40, '1. Spoel de rijst en breng hem met de melk en de suiker aan de kook.
2. Laat op laag vuur in ongeveer 30 minuten gaar worden tot de melk is opgenomen; roer geregeld.
3. Roer de kaneel erdoor en strooi de cranberry''s erover. Warm of koud te eten.', 'Australian Institute of Sport', 'https://www.ausport.gov.au/nutrition/recipes/creamed_rice', true, null),
  ('krentenbollen-jam', 'Krentenbollen met jam', 'voor_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 2, '1. Snijd de krentenbollen open en besmeer ze met de jam.', null, null, true, null),
  ('pannenkoek-stroop', 'Pannenkoeken met stroop', 'voor_rit', 'hoog_kh', array['vegetarisch']::text[], 2, 20, '1. Klop de pannenkoekmix met de melk tot een glad beslag.
2. Bak in de olie vier dunne pannenkoeken.
3. Schenk de stroop erover.', null, null, true, null),
  ('ontbijtkoek-banaan', 'Ontbijtkoek met banaan', 'voor_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 1, '1. Snijd drie plakken ontbijtkoek en eet de banaan erbij.', null, null, true, null),
  ('pasta-tomaat-licht', 'Witte pasta met lichte tomatensaus', 'voor_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 15, '1. Kook de pasta gaar.
2. Verwarm de gezeefde tomaat met de olie, het zout en het basilicum en meng met de pasta.', null, null, true, null),
  ('rijstwafels-honing-banaan', 'Rijstwafels met honing en banaan', 'voor_rit', 'hoog_kh', array['vegetarisch', 'glutenvrij', 'lactosevrij']::text[], 1, 2, '1. Besmeer de rijstwafels met de honing en beleg met plakjes banaan.', null, null, true, null),
  ('smoothie-banaan-haver', 'Smoothie van banaan, haver en sinaasappelsap', 'voor_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 5, '1. Pureer de banaan met de havervlokken, het sinaasappelsap en de ahornsiroop tot een gladde smoothie.', null, null, true, null),
  ('witte-broodjes-kipfilet', 'Witte broodjes met kipfilet', 'voor_rit', 'hoog_kh', array[]::text[], 1, 3, '1. Snijd de broodjes open en beleg ze met de kipfilet.
2. Drink er het appelsap bij.', null, null, true, null),
  ('krentenbol-jam-onderweg', 'Krentenbol met jam', 'tijdens_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 2, '1. Snijd de krentenbol open, besmeer met de jam en verpak hem in folie.', null, null, true, null),
  ('banaan-ontbijtkoek', 'Banaan en ontbijtkoek', 'tijdens_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 1, '1. Snijd de ontbijtkoek in twee plakken en verpak ze. Neem de banaan in je achterzak mee.', null, null, true, null),
  ('wit-broodje-jam', 'Zacht wit broodje met jam', 'tijdens_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 2, '1. Snijd het broodje open, besmeer royaal met de jam en verpak het in folie.', null, null, true, null),
  ('sandwich-pindakaas-jam', 'Sandwich met pindakaas en jam', 'tijdens_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 3, '1. Besmeer één snee brood dun met de pindakaas en de andere met de jam.
2. Leg ze op elkaar, snijd doormidden en verpak in folie.', null, null, true, null),
  ('haverkoekjes-banaan', 'Haverkoekjes met banaan en rozijnen', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 6, 25, '1. Prak de bananen en meng ze met de havervlokken, de rozijnen, de ahornsiroop en het zout.
2. Vorm 12 koekjes op een bakplaat met bakpapier.
3. Bak 15 minuten op 180 °C. Twee koekjes zijn één portie.', null, null, true, null),
  ('zoute-aardappeltjes', 'Gekookte aardappeltjes met zout', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 1, 20, '1. Kook de aardappeltjes in de schil in 15 minuten gaar en laat ze afkoelen.
2. Bestrooi met het zout, schenk de siroop erover en neem ze mee in een zakje.', null, null, true, null),
  ('dadels-winegums', 'Dadels en winegums', 'tijdens_rit', 'hoog_kh', array['lactosevrij']::text[], 1, 1, '1. Doe de dadels en de winegums samen in een zakje voor in je achterzak.', null, null, true, null),
  ('appelsap-sportdrank', 'Sportdrank van appelsap', 'tijdens_rit', 'hoog_kh', array['vegetarisch', 'vegan', 'glutenvrij', 'lactosevrij']::text[], 1, 2, '1. Meng het appelsap met het water, de suiker en het zout in een bidon en schud tot alles is opgelost.', null, null, true, null),
  ('mueslireep-banaan', 'Mueslireep en banaan', 'tijdens_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 1, '1. Neem de mueslireep en de banaan mee in je achterzak.', null, null, true, null),
  ('kwark-banaan-muesli', 'Kwark met banaan en muesli', 'na_rit', 'gemengd', array['vegetarisch']::text[], 1, 3, '1. Schep de kwark in een kom en snijd de banaan erboven in plakjes.
2. Strooi de muesli erover en maak af met de honing.', null, null, true, null),
  ('rijst-kip-snel', 'Snelle rijst met kip en doperwten', 'na_rit', 'hoog_kh', array['glutenvrij', 'lactosevrij']::text[], 1, 20, '1. Kook de rijst gaar en kook de doperwten de laatste 3 minuten mee.
2. Bak de kipblokjes in de olie gaar met het paprikapoeder en het zout.
3. Schep alles door elkaar.', null, null, true, null),
  ('wrap-omelet', 'Wrap met omelet en tomaat', 'na_rit', 'gemengd', array['vegetarisch']::text[], 1, 8, '1. Klop de eieren los met peper en zout en bak er in de olie een omelet van.
2. Leg de omelet op de wraps met de tomaat in plakjes en rol ze op.
3. Drink er het sinaasappelsap bij.', null, null, true, null),
  ('smoothie-skyr-bessen', 'Herstelsmoothie met skyr en bessen', 'na_rit', 'gemengd', array['vegetarisch']::text[], 1, 5, '1. Pureer de skyr met de banaan, de bessen, de havervlokken, de honing en de melk tot een gladde smoothie.', null, null, true, null),
  ('broodjes-ei-ham', 'Broodjes met ei en ham', 'na_rit', 'gemengd', array[]::text[], 1, 10, '1. Kook het ei in 8 minuten hard en snijd het in plakjes.
2. Beleg de broodjes met de ham en het ei.
3. Drink er het appelsap bij.', null, null, true, null),
  ('vla-banaan-cornflakes', 'Vla met banaan en cornflakes', 'na_rit', 'hoog_kh', array['vegetarisch']::text[], 1, 3, '1. Roer de kwark door de vla.
2. Snijd de banaan erboven in plakjes en strooi de cornflakes erover.', null, null, true, null),
  ('pasta-tonijn-snel', 'Snelle pasta met tonijn', 'na_rit', 'hoog_kh', array['lactosevrij']::text[], 1, 15, '1. Kook de pasta gaar.
2. Verwarm de gezeefde tomaat met de uitgelekte tonijn en de olie.
3. Meng met de pasta.', null, null, true, null),
  ('sojashake-banaan-haver', 'Plantaardige herstelshake', 'na_rit', 'gemengd', array['vegetarisch', 'vegan', 'lactosevrij']::text[], 1, 5, '1. Pureer de sojadrink met de banaan, de havervlokken, de pindakaas en de ahornsiroop tot een gladde shake.', null, null, true, null),
  ('yoghurt-honing-rijstwafels', 'Griekse yoghurt met honing en rijstwafels', 'na_rit', 'gemengd', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Roer de honing door de yoghurt.
2. Eet de rijstwafels met jam ernaast.', null, null, true, null),
  ('pannenkoeken-kwark-fruit', 'Pannenkoeken met kwark en aardbeien', 'na_rit', 'gemengd', array['vegetarisch']::text[], 2, 20, '1. Klop de pannenkoekmix met de melk en het ei tot een glad beslag en bak in de olie vier pannenkoeken.
