  ('skyr-banaan-honing', 'Skyr met banaan en honing', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 2, '1. Schep de skyr in een kom, snijd de banaan erboven in plakjes en schenk de honing erover.', null, null, true, null),
  ('griekse-yoghurt-frambozen', 'Magere Griekse yoghurt met frambozen en amandelen', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 2, '1. Schep de yoghurt in een kom en verdeel de frambozen en de amandelen erover.', null, null, true, null),
  ('kwark-appel-kaneel', 'Kwark met appel en kaneel', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Snijd de appel in blokjes en schep ze met de kaneel door de kwark.', null, null, true, null),
  ('huttenkase-roggebrood', 'Hüttenkäse op roggebrood', 'voor_slapen', 'eiwitrijk', array['vegetarisch']::text[], 1, 3, '1. Verdeel de hüttenkäse over het roggebrood.
