  ('kwarkshake-cacao', 'Kwarkshake met cacao', 'voor_slapen', 'eiwitrijk', array['vegetarisch', 'glutenvrij']::text[], 1, 3, '1. Mix de kwark met de melk, de cacao en de honing tot een gladde shake.', null, null, true, null),
